ops.template:
// Generated by the Bugsee wizard. Injects debug ids into the built JavaScript and uploads its source maps.
// Usage: node scripts/bugsee-sourcemaps.mjs [outputDir]   (default: $BUGSEE_SOURCEMAPS_DIR, then ./dist)
// The app token comes from BUGSEE_APP_TOKEN, or from .env.bugsee-build-plugin (never committed).
import { spawnSync } from 'node:child_process';
import { existsSync, readFileSync } from 'node:fs';

const out = process.argv[2] || process.env.BUGSEE_SOURCEMAPS_DIR || 'dist';
if (!existsSync(out)) {
  console.error(`bugsee: output directory "${out}" not found. Build first, or pass the directory as an argument.`);
  process.exit(1);
}

const envFile = '.env.bugsee-build-plugin';
if (!process.env.BUGSEE_APP_TOKEN && existsSync(envFile)) {
  for (const line of readFileSync(envFile, 'utf8').split(/\r?\n/)) {
    const m = /^BUGSEE_APP_TOKEN=(.*)$/.exec(line.trim());
    if (m) process.env.BUGSEE_APP_TOKEN = m[1].replace(/^["']|["']$/g, '');
  }
}
if (!process.env.BUGSEE_APP_TOKEN) {
  console.error('bugsee: BUGSEE_APP_TOKEN is not set (environment or .env.bugsee-build-plugin).');
  process.exit(1);
}

const pkg = JSON.parse(readFileSync('package.json', 'utf8'));
const version = process.env.BUGSEE_APP_VERSION || pkg.version || '0.0.0';
const git = spawnSync('git', ['rev-list', '--count', 'HEAD'], { encoding: 'utf8' });
const build =
  process.env.BUGSEE_BUILD || process.env.GITHUB_RUN_NUMBER || process.env.BUILD_NUMBER ||
  (git.status === 0 ? git.stdout.trim() : '') || '1';

function run(args) {
  const r = spawnSync('npx', ['--no-install', 'bugsee-cli', ...args], { stdio: 'inherit', shell: process.platform === 'win32' });
  if (r.status !== 0) process.exit(r.status ?? 1);
}

run(['sourcemaps', 'inject', out]);
run(['debug-files', 'upload', out, '--type', 'sourcemaps', '--version', version, '--build', build]);
